from PIL import Image
im = Image.open('/tmp/full_screen.png')
# let's find the y ranges of blue text
matches_by_y = {}
for y in range(450, 850):
    count = 0
    for x in range(250, 700):
        r, g, b = im.getpixel((x, y))[:3]
        if r < 50 and 60 < g < 130 and b > 140:
            count += 1
    if count > 5:
        matches_by_y[y] = count

print('Y coordinates with blue text:')
for y in sorted(matches_by_y.keys()):
    print(f'y={y}: {matches_by_y[y]} pixels')
"

